import{_ as t,o,c as a,ak as s}from"./chunks/framework.sV-XtlWr.js";const g=JSON.parse('{"title":"Browser extension","description":"","frontmatter":{"title":"Browser extension","lang":"en-US"},"headers":[],"relativePath":"extension.md","filePath":"extension.md","lastUpdated":1785271955000}'),i={name:"extension.md"};function n(r,e,c,l,d,h){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="browser-extension" tabindex="-1">Browser extension <a class="header-anchor" href="#browser-extension" aria-label="Permalink to &quot;Browser extension&quot;">​</a></h1><p>Piwi Picker is a Chrome/Edge extension (Manifest V3) that picks ranked, stable Playwright locators directly from the page you&#39;re looking at — scored by the same engine the dashboard uses. It&#39;s standalone: this phase talks to no server, sends nothing anywhere, and requests <code>activeTab</code>, <code>scripting</code>, and <code>storage</code> only.</p><blockquote><p>Not yet published to the Chrome Web Store or Edge Add-ons. Install it unpacked from a local build until it is.</p></blockquote><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/PiwiTests/platform.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> platform</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extension:build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace=extension</span></span></code></pre></div><p>Then, in Chrome or Edge:</p><ol><li>Open <code>chrome://extensions</code> (<code>edge://extensions</code> on Edge).</li><li>Turn on <strong>Developer mode</strong>.</li><li><strong>Load unpacked</strong> → select <code>extension/dist</code>.</li></ol><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><ul><li><strong>Pick an element</strong> — click the toolbar icon → <strong>Pick an element</strong>, or press <code>Ctrl+Shift+E</code> (<code>Cmd+Shift+E</code> on macOS) on any page. Hover highlights, a click picks — the pick snaps to the nearest actionable ancestor (a click on the text inside a button picks the button), and ↑/↓ walk the DOM tree before it commits. When the element has a role, an <strong>anchors</strong> step follows: bless one or more stable parent elements to scope the locator to, with a live &quot;matches N&quot; count.</li><li><strong>Ranked locators, re-checked live</strong> — every candidate is scored the way the dashboard scores captured locators, then re-counted against the page as it is right now (a page can re-render between the pick and reviewing the results). A candidate that&#39;s become ambiguous is shown with its current match count and a suggestion to add <code>.first()</code> or <code>.filter({ hasText: … })</code> — never silently dropped.</li><li><strong>Copy in three forms</strong> — the bare locator, a full action line (<code>await page.getByRole(…).click();</code>), or a visibility assertion (<code>await expect(page.getByRole(…)).toBeVisible();</code>). Your last-used form is remembered for next time.</li><li><strong>Hover-inspect</strong> — toggle from the popup: hover any element to see its best-ranked locator in a tooltip, no click needed.</li><li><strong>Locator console</strong> — type or paste a locator expression (a safe subset — <code>getBy*</code> chains, <code>locator(css)</code>, <code>filter({ hasText })</code>, <code>.first()</code>/<code>.last()</code>/<code>.nth()</code> — parsed, never <code>eval</code>&#39;d) and see every match highlighted on the page live, with a strict-mode verdict and count.</li><li><strong>Multi-pick pattern derivation</strong> — pick 2–3 similar items (table rows, cards) and derive the shared list pattern (e.g. <code>getByRole(&#39;row&#39;).filter({ hasText: … })</code>), with a warning when only index-based (<code>.nth()</code>) discrimination was possible.</li><li><strong>Lint overlay</strong> — one click outlines every interactive element on the page that would score badly as a locator target right now (no test id, no accessible name, no stable structural anchor), with a suggested <code>data-testid</code> per element and a one-click Markdown checklist export.</li><li><strong>Assertion suggester</strong> — pick an element and get ranked <code>expect(...)</code> candidates built against its top-ranked locator — whichever of <code>toHaveValue</code>, <code>toHaveText</code>, <code>toHaveAccessibleName</code>, and <code>toBeVisible</code> actually apply to it — with a one-click copy per candidate.</li><li><strong>Session</strong> — pick and name elements as you browse, even across different pages, then export the whole named list as a Playwright POM-style fixture class, a Markdown table (paste into a PR description or issue), or JSON. The session lives for as long as the browser stays open — see <a href="#permissions-explained">Permissions</a>.</li><li><strong>Copy context for agent</strong> — pick an element and copy one paste-able block for an AI coding agent: the page URL, a compact element summary (tag, role, accessible name, key attributes, text), and every ranked locator alternative.</li></ul><h2 id="permissions-explained" tabindex="-1">Permissions, explained <a class="header-anchor" href="#permissions-explained" aria-label="Permalink to &quot;Permissions, explained&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Why</th></tr></thead><tbody><tr><td><code>activeTab</code></td><td>Lets the extension act on the tab you&#39;re looking at only when you click the toolbar icon or press the keyboard shortcut — not on every page you visit.</td></tr><tr><td><code>scripting</code></td><td>Injects the picker into the active tab on demand (see above) — there is no background content script running on pages you haven&#39;t asked it to.</td></tr><tr><td><code>storage</code></td><td>Remembers your last-used copy format, and the named pick session if you use one, locally on your machine. The session specifically uses <code>chrome.storage.session</code>, which the browser clears when you close it — it&#39;s a working session, not a saved file.</td></tr></tbody></table><p>Nothing here reaches a network. There is no host permission, no <code>&lt;all_urls&gt;</code>, and no remote code — the entire extension is the code in this repository, bundled as-is.</p><h2 id="current-limits" tabindex="-1">Current limits <a class="header-anchor" href="#current-limits" aria-label="Permalink to &quot;Current limits&quot;">​</a></h2><ul><li><strong>One frame at a time.</strong> Picking inside an iframe, or across shadow DOM boundaries, isn&#39;t supported yet — the picker sees the top-level document.</li><li><strong>No aria-snapshot copier yet.</strong> Reproducing Playwright&#39;s <code>toMatchAriaSnapshot()</code> YAML format exactly needs the browser&#39;s real computed accessibility tree, which isn&#39;t reachable from a content script without a much heavier permission (<code>debugger</code>) than this extension asks for. An approximated version risks copying YAML that looks right but doesn&#39;t actually match — worse than not offering it. The copy-context-for-agent element summary is deliberately a simpler, non-recursive approximation instead (tag/role/name/attributes/text) rather than the same aria-snapshot format — fine for giving an AI agent context, not meant for a <code>toMatchAriaSnapshot()</code> assertion.</li><li><strong>Live re-check covers the common shapes.</strong> <code>getByTestId</code>, CSS locators, and a bare <code>getByRole</code> are re-verified against the page as it is now; text/label/placeholder-based matches and anchor-scoped chains keep the count captured at pick time (Playwright&#39;s own text-matching rules aren&#39;t reproduced here).</li><li><strong>No dashboard connection in this phase.</strong> Nothing is sent to your Piwi instance yet — that&#39;s planned as an opt-in later phase, kept clearly separate from this standalone path.</li></ul><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><p><code>extension/</code> in the <a href="https://github.com/PiwiTests/platform" target="_blank" rel="noreferrer">monorepo</a> — see <a href="https://github.com/PiwiTests/platform/blob/main/extension/AGENTS.md" target="_blank" rel="noreferrer"><code>extension/AGENTS.md</code></a> for how it&#39;s built and tested.</p>`,16)])])}const m=t(i,[["render",n]]);export{g as __pageData,m as default};
